def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []

    # Find connected components that form rectangular outlines.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            top = min(y for y, x in comp)
            bottom = max(y for y, x in comp)
            left = min(x for y, x in comp)
            right = max(x for y, x in comp)
            if bottom - top < 2 or right - left < 2:
                continue

            border = set()
            for x in range(left, right + 1):
                border.add((top, x))
                border.add((bottom, x))
            for y in range(top, bottom + 1):
                border.add((y, left))
                border.add((y, right))
            if all(grid[y][x] == color for y, x in border):
                frames.append((top, bottom, left, right, color, border))

    out = [[0] * w for _ in range(h)]
    frame_cells = set()
    for top, bottom, left, right, color, border in frames:
        frame_cells |= border
        for y, x in border:
            out[y][x] = color

    counts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in frame_cells:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    # Match each frame to a speckle color by the number of cells in its
    # checkerboard fill, choosing the overall closest one-to-one assignment.
    colors = list(counts)
    if frames and colors:
        best = None

        def assign(i, used, pairs, cost):
            nonlocal best
            if i == len(frames):
                if best is None or cost < best[0]:
                    best = (cost, pairs[:])
                return
            top, bottom, left, right, _, _ = frames[i]
            ih, iw = bottom - top - 1, right - left - 1
            target = (ih * iw + 1) // 2
            for color in colors:
                if color not in used:
                    pairs.append(color)
                    assign(i + 1, used | {color}, pairs,
                           cost + abs(counts[color] - target))
                    pairs.pop()

        if len(colors) >= len(frames):
            assign(0, set(), [], 0)
        else:
            # Fallback if there are fewer speckle colors than frames.
            best = (0, [colors[i % len(colors)] for i in range(len(frames))])

        if best:
            for (top, bottom, left, right, _, _), fill in zip(frames, best[1]):
                for y in range(top + 1, bottom):
                    for x in range(left + 1, right):
                        if (y - top - 1 + x - left - 1) % 2 == 0:
                            out[y][x] = fill

    return out
